// TH14 v1.00b Stage 5 Boss, first nonspell: st05bs.ecl.txt::Boss1 (source lines 61-89).
// Entry state comes from the Boss prologue (st05bs.ecl.txt:10-35, the first 35 lines up to
// bossEntry wait 102); dialogWait / setBoss / CAPTURE / fog / lifeMarker / stars / anm are the
// approved presentation-or-stat omissions. Sub-enemies: none. Lasers: none.

const TIME_LIMIT: int = 2826;   // 120 opening + 2702 window (2100 native + 102 entry + 500 tail) + 4 startup
const OPENING_BUFFER: int = 120;
const SEGMENT_LIMIT: int = 2100;  // setInterrupt(0, 2600, 2100, "BossCard1") time slot; HP slot unreachable (no DPS)

// Source Boss1_at EX chain (lines 109-116) / Boss1_at2 chain (lines 161-168), all async=0 so the
// records run in order while each VELTIME lasts.
//   ANIM a=1                     -> birth stage omitted; its 4*initial-speed retreat (4*2.0 px) is
//                                   folded into sh_dist below, per transcription policy.
//   VELTIME a=30 r=1.0 s=-999999 -> scalar speed 2.0 -> 1.0 over 30 frames, angle kept.
//   SETSPRITE a=8 b=<col>        -> TH14_RICE (same 2.4 radius, so no radius-refresh difference).
//   PLAYSOUND 38                 -> omitted (pure sound).
//   VELTIME a=50 r=<mid>         -> 1.0 -> 3.0 (Boss1_at) or 1.0 -> 1.4 (Boss1_at2) over 50 frames.
//   SETSPRITE a=15 b=<col>       -> TH14_INVERT_RICE.
//   PLAYSOUND 39                 -> omitted.
//   VELTIME a=60 r=0.5           -> 3.0 (or 1.4) -> 0.5 over 60 frames.
xformdef BOSS1_DANCE(col: int, mid: fx) {
    @30 step_speed(1fx, 30);
    set_sprite(TH14_RICE, col);
    @50 step_speed(mid, 50);
    set_sprite(TH14_INVERT_RICE, col);
    step_speed(0.5fx, 60);
}

// Boss1_at (source 91-141): I0 volleys, base angle drawn once from RANDRAD, +F0 per volley,
// etDist 96 reduced by 8 per volley. Called synchronously, so it finishes before Boss1_at2 starts.
sub boss1_at(i0: int, n: int, step: int, volley_wait: int, t0: int) {
    var a: int = rand(65536);       // %A = %RANDRAD (uniform -pi..pi)
    var b: fx = 96fx;               // %B = 96
    var c: int = i0;
    sh_reset(0);
    sh_sprite(0, TH14_INVERT_RICE, 2);   // etSprite(0, 15, 2)
    sh_ring(0, 1);                       // etAim(0, 3): fixed-direction full ring
    sh_aim(0, 0);
    sh_count(0, n, 1);                   // etCount(0, <16|24|26|30>, 1)
    sh_speed(0, 2fx, 0fx);               // etSpeed(0, 2.0, 1.0) with one layer -> 2.0
    sh_angle(0, a as angle, 0deg);       // etAngle(0, 1.5707964, 0.032724924) is overwritten per volley
    sh_xform(0, BOSS1_DANCE(2, 3fx));
    while c > 0 && $frame - t0 < SEGMENT_LIMIT {
        sh_angle(0, a as angle, 0deg);   // etAngle(0, %A, 0.0)
        sh_dist(0, b - 8fx);             // etDist(0, %B) plus ANIM a=1 retreat 4*2.0
        a = a + step;                    // %A = %A + %F0
        b = b - 8fx;                     // %B = %B - 8
        sh_fire(0);                      // etOn(0)
        wait(volley_wait);               // !E 4; !N/!H/!LO 3
        c = c - 1;                       // if ($C--) goto loop
    }
}

// Boss1_at2 (source 143-184): same geometry, opposite rotation, fixed 3-frame volley wait,
// color 6 and a 1.4 mid speed.
sub boss1_at2(i0: int, n: int, step: int, t0: int) {
    var a: int = rand(65536);       // %A = %RANDRAD
    var b: fx = 96fx;               // %B = 96
    var c: int = i0;
    sh_reset(1);
    sh_sprite(1, TH14_INVERT_RICE, 6);   // etSprite(1, 15, 6)
    sh_ring(1, 1);                       // etAim(1, 3)
    sh_aim(1, 0);
    sh_count(1, n, 1);                   // etCount(1, <16|24|28|32>, 1)
    sh_speed(1, 2fx, 0fx);               // etSpeed(1, 2.0, 1.0), one layer
    sh_angle(1, a as angle, 0deg);
    sh_xform(1, BOSS1_DANCE(6, 1.4fx));
    while c > 0 && $frame - t0 < SEGMENT_LIMIT {
        sh_angle(1, a as angle, 0deg);
        sh_dist(1, b - 8fx);
        a = a - step;                    // %A = %A - %F0
        b = b - 8fx;
        sh_fire(1);
        wait(3);                         // source line 180: unconditional wait(3)
        c = c - 1;
    }
}

// moveRand(60, 4, 1.0) with moveLimit(0, 128, 280, 64): direction inner box is x +/-70, y 112..144;
// the position limit box is x +/-140, y 96..160. Speed ramps 1 -> 0 over 60 ticks and the limit
// clamps every frame (th16/movement.md verified sample, constants re-derived from this limit).
// Boss shared slots: int0 = armed step count, fx0/fx1 = logical direction unit vector.
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60-k) as fx / 60; }
    var nx: fx = $self_x+self_fx(0)*speed;
    var ny: fx = $self_y+self_fx(1)*speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -70fx {
        a = r/3;
    } else if $self_x > 70fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }         // source normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad; nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// Boss1 (source 61-89). timerReset/setInterrupt/lifeMarker are the entry segment state; the
// interrupt's next-attack target ("BossCard1") is only the end boundary and is not executed.
sub boss1_main() {
    var rank: int = global(GVAR_RANK);
    var i0: int = 7;                // diffI($I0, 7, 10, 12, 12)
    var count_a: int = 16;          // etCount stacks 16/24/26/30
    var count_b: int = 16;          // etCount stacks 16/24/28/32
    var volley_wait: int = 4;       // !E 4; others 3
    if rank >= 1 { i0 = 10; count_a = 24; count_b = 24; volley_wait = 3; }
    if rank >= 2 { i0 = 12; count_a = 26; count_b = 28; }
    if rank >= 3 { count_a = 30; count_b = 32; }
    var step: int = 419;            // %F0 = 0.040143 rad -> 419 BAM (~2.3 deg)
    var t0: int = $frame;           // timerReset point
    set_self_int(0, 60);            // movement idle until the first moveRand
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    while $frame - t0 < SEGMENT_LIMIT {
        // anmPlay(1,72) / playSound(54) omitted (presentation)
        card_wait(60);                                    // wait(60) runs the previous moveRand ramp
        boss1_at(i0, count_a, step, volley_wait, t0);
        boss1_at2(i0, count_b, step, t0);
        wait(10);
        // anmSelectedPlay(0) omitted
        wait(60);
        // anm316(0,-1) omitted
        step = 0-step;                                    // %F0 = %F0 * -1
        wait(60);
        card_move_rand();                                 // moveRand(60, 4, 1.0)
        i0 = i0+1;                                        // $I0 = $I0 + 1
        // EffChargePoint2 omitted (anm + sound only)
    }
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);                // drop any armed partial moveRand step
    loop { wait(1); }                                     // segment over: stop firing, boss stays
}

// Boss prologue (source 10-35, up to the 102-frame entry wait): setBoss/CAPTURE/lifeSet/fog/anm
// are shell or presentation state. movePos(0,128) is the spawn point; the transient
// setInvuln(120)/setInvuln(60) become the training shell's permanent invulnerability.
async sub boss_entry() {
    set_invuln(65535);
    set_hitbox(24fx);               // setHitbox(48, 48): normal circle branch, radius 24
    set_hurtbox(24fx);              // setHurtbox(48, 48)
    wait(102);                      // source line 20; dialogWait omitted
    boss1_main();
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 13600, 0, 0, 0, boss_entry);   // lifeSet(13600)
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

// TH14 bullet mapping (transcribe/th14/touhou-bullets.ecl). Only the types used by this card.
// Source type 0-23 map to the same target slot; source etSprite(15,*) is TH14_INVERT_RICE,
// EX SETSPRITE a=8 is TH14_RICE. Both have native base radius 2.4 px.
const TH14_RICE: int = 480;
const TH14_INVERT_RICE: int = 592;
